1	import { randomUUID } from "node:crypto";
2	import type { Pool, PoolClient } from "pg";
3	import {
4	  appendAuditEvent,
5	  hashAuditSourceIp,
6	  hashAuditUserAgent,
7	  type AuditSourceIpKdfParameters,
8	  type CryptoEnvelope
9	} from "@debateai/crypto";
10	
11	export interface AuthSourceContext {
12	  readonly ip: string;
13	  readonly userAgent: string;
14	  readonly requestId: string;
15	}
16	
17	export interface PendingAccountInput {
18	  readonly userId: string;
19	  readonly emailBlindIndex: Buffer;
20	  readonly emailCiphertext: CryptoEnvelope;
21	  readonly recoveryEmailCiphertext: CryptoEnvelope;
22	  readonly passwordHash: string;
23	  readonly pseudonym: string;
24	  readonly auditToken: string;
25	  readonly adultAffirmedAt: Date;
26	  readonly verificationTokenHash: string;
27	  readonly verificationExpiresAt: Date;
28	  readonly occurredAt: Date;
29	  readonly source: AuthSourceContext;
30	}
31	
32	export type PendingAccountResult =
33	  | Readonly<{ status: "created"; userId: string; auditToken: string; channelBindingId: string }>
34	  | Readonly<{ status: "email_duplicate"; userId: string }>
35	  | Readonly<{ status: "pseudonym_collision" }>;
36	
37	export type ResendPreparation =
38	  | Readonly<{ status: "send"; userId: string; auditToken: string; channelBindingId: string }>
39	  | Readonly<{ status: "ignored" }>;
40	
41	interface AuditWrite {
42	  readonly actorToken: string;
43	  readonly eventType: string;
44	  readonly targetType: string;
45	  readonly occurredAt: Date;
46	  readonly source: AuthSourceContext;
47	  readonly decision: "ALLOW" | "DENY";
48	  readonly success: boolean;
49	  readonly justification: string | null;
50	}
51	
52	function assertOpaqueToken(value: string): void {
53	  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)) {
54	    throw new TypeError("AUDIT_TOKEN_MUST_BE_RANDOM_UUID_V4");
55	  }
56	}
57	
58	function normalizeAuditContextValue(value: unknown, maximumLength: number): string {
59	  const trimmed = typeof value === "string" ? value.trim() : "";
60	  return (trimmed === "" ? "unknown" : trimmed).slice(0, maximumLength);
61	}
62	
63	function normalizeAuditSourceContext(source: AuthSourceContext): AuthSourceContext {
64	  return Object.freeze({
65	    ip: normalizeAuditContextValue(source?.ip, 64),
66	    userAgent: normalizeAuditContextValue(source?.userAgent, 256),
67	    requestId: normalizeAuditContextValue(source?.requestId, 128)
68	  });
69	}
70	
71	export class PostgresIdentityRepository {
72	  private readonly sourceIpSalt: Buffer;
73	  private readonly sourceIpKdf: AuditSourceIpKdfParameters;
74	
75	  constructor(
76	    private readonly pool: Pool,
77	    sourceIpSalt: Uint8Array,
78	    sourceIpKdf: AuditSourceIpKdfParameters
79	  ) {
80	    if (sourceIpSalt.byteLength < 32) throw new TypeError("AUDIT_SOURCE_IP_SALT_INVALID");
81	    this.sourceIpSalt = Buffer.from(sourceIpSalt);
82	    this.sourceIpKdf = Object.freeze({ ...sourceIpKdf });
83	  }
84	
85	  private async transaction<T>(operation: (client: PoolClient) => Promise<T>): Promise<T> {
86	    const client = await this.pool.connect();
87	    try {
88	      await client.query("BEGIN");
89	      const result = await operation(client);
90	      await client.query("COMMIT");
91	      return result;
92	    } catch (error) {
93	      await client.query("ROLLBACK");
94	      throw error;
95	    } finally {
96	      client.release();
97	    }
98	  }
99	
100	  private async appendAudit(client: PoolClient, event: AuditWrite): Promise<void> {
101	    assertOpaqueToken(event.actorToken);
102	    const source = normalizeAuditSourceContext(event.source);
103	    const ipArgon2id = await hashAuditSourceIp(source.ip, this.sourceIpSalt, this.sourceIpKdf);
104	    const userAgentArgon2id = await hashAuditUserAgent(
105	      source.userAgent, this.sourceIpSalt, this.sourceIpKdf
106	    );
107	    await client.query("SELECT pg_advisory_xact_lock(hashtextextended('identity:audit-chain', 0))");
108	    const head = await client.query<{ this_hash: Buffer }>(`
109	      SELECT parent.this_hash
110	      FROM identity.audit_event parent
111	      LEFT JOIN identity.audit_event child ON child.prev_hash=parent.this_hash
112	      WHERE child.audit_id IS NULL
113	      ORDER BY parent.occurred_at DESC,parent.audit_id DESC
114	      LIMIT 1
115	    `);
116	    const previous = head.rows[0]?.this_hash.toString("hex") ?? null;
117	    const payload = Object.freeze({
118	      auditId: randomUUID(),
119	      actorCiphertext: null,
120	      actorKeyRef: event.actorToken,
121	      eventType: event.eventType,
122	      targetType: event.targetType,
123	      targetId: event.actorToken,
124	      occurredAt: event.occurredAt,
125	      sourceContext: Object.freeze({
126	        ipArgon2id,
127	        userAgentArgon2id
128	      }),
129	      decision: event.decision,
130	      success: event.success,
131	      justification: event.justification
132	    });
133	    const chained = appendAuditEvent(previous, payload);
134	    await client.query(`
135	      INSERT INTO identity.audit_event (
136	        audit_id,prev_hash,this_hash,actor_ciphertext,actor_key_ref,event_type,
137	        target_type,target_id,occurred_at,source_context,decision,success,justification
138	      ) VALUES ($1,$2,$3,NULL,$4,$5,$6,$4,$7,$8::jsonb,$9,$10,$11)
139	    `, [
140	      chained.auditId,
141	      chained.prevHash === null ? null : Buffer.from(chained.prevHash, "hex"),
142	      Buffer.from(chained.thisHash, "hex"),
143	      chained.actorKeyRef,
144	      chained.eventType,
145	      chained.targetType,
146	      chained.occurredAt,
147	      JSON.stringify(chained.sourceContext),
148	      chained.decision,
149	      chained.success,
150	      chained.justification
151	    ]);
152	  }
153	
154	  async createPendingAccount(
155	    input: PendingAccountInput,
156	    beforeCommit: () => Promise<void>
157	  ): Promise<PendingAccountResult> {
158	    return this.transaction(async (client) => {
159	      const inserted = await client.query<{ user_id: string }>(`
160	        INSERT INTO identity."user" (
161	          user_id,email_blind_index,email_ciphertext,recovery_email_ciphertext,
162	          phone_ciphertext,password_hash,pseudonym,audit_token,state,adult_affirmed_at,created_at
163	        ) VALUES ($1,$2,$3::jsonb,$4::jsonb,NULL,$5,$6,$7,'pending_verification',$8,$9)
164	        ON CONFLICT DO NOTHING
165	        RETURNING user_id
166	      `, [
167	        input.userId,
168	        input.emailBlindIndex,
169	        JSON.stringify(input.emailCiphertext),
170	        JSON.stringify(input.recoveryEmailCiphertext),
171	        input.passwordHash,
172	        input.pseudonym,
173	        input.auditToken,
174	        input.adultAffirmedAt,
175	        input.occurredAt
176	      ]);
177	      if (inserted.rowCount === 0) {
178	        const duplicate = await client.query<{ user_id: string; audit_token: string }>(`
179	          SELECT user_id,audit_token FROM identity."user" WHERE email_blind_index=$1
180	        `, [input.emailBlindIndex]);
181	        const existing = duplicate.rows[0];
182	        if (existing === undefined) {
183	          return Object.freeze({ status: "pseudonym_collision" as const });
184	        }
185	        await client.query(`
186	          UPDATE identity."user" SET state=state WHERE user_id=$1
187	        `, [existing.user_id]);
188	        await client.query(`
189	          UPDATE identity.channel_binding SET state=state
190	          WHERE user_id=$1 AND channel_type='email'
191	        `, [existing.user_id]);
192	        await client.query(`
193	          UPDATE identity.channel_binding SET state=state
194	          WHERE user_id=$1 AND channel_type='recovery_email'
195	        `, [existing.user_id]);
196	        await this.appendAudit(client, {
197	          actorToken: existing.audit_token,
198	          eventType: "identity.registration",
199	          targetType: "identity.user",
200	          occurredAt: input.occurredAt,
201	          source: input.source,
202	          decision: "DENY",
203	          success: false,
204	          justification: "REGISTRATION_ADDRESS_UNAVAILABLE"
205	        });
206	        return Object.freeze({ status: "email_duplicate" as const, userId: existing.user_id });
207	      }
208	      const emailChannel = await client.query<{ channel_binding_id: string }>(`
209	        INSERT INTO identity.channel_binding (
210	          user_id,channel_type,address_ciphertext,state,created_at,
211	          verification_token_hash,verification_expires_at,verification_last_sent_at,delivery_status
212	        ) VALUES ($1,'email',$2::jsonb,'pending_verification',$3,$4,$5,$3,'pending')
213	        RETURNING channel_binding_id
214	      `, [
215	        input.userId,
216	        JSON.stringify(input.emailCiphertext),
217	        input.occurredAt,
218	        input.verificationTokenHash,
219	        input.verificationExpiresAt
220	      ]);
221	      await client.query(`
222	        INSERT INTO identity.verification_token_credential (
223	          token_hash,channel_binding_id,issued_at,expires_at
224	        ) VALUES ($1,$2,$3,$4)
225	      `, [
226	        input.verificationTokenHash,
227	        emailChannel.rows[0]!.channel_binding_id,
228	        input.occurredAt,
229	        input.verificationExpiresAt
230	      ]);
231	      await client.query(`
232	        INSERT INTO identity.channel_binding (
233	          user_id,channel_type,address_ciphertext,state,created_at,delivery_status
234	        ) VALUES ($1,'recovery_email',$2::jsonb,'pending_verification',$3,'not_requested')
235	      `, [input.userId, JSON.stringify(input.recoveryEmailCiphertext), input.occurredAt]);
236	      await this.appendAudit(client, {
237	        actorToken: input.auditToken,
238	        eventType: "identity.registration",
239	        targetType: "identity.user",
240	        occurredAt: input.occurredAt,
241	        source: input.source,
242	        decision: "ALLOW",
243	        success: true,
244	        justification: null
245	      });
246	      await beforeCommit();
247	      return Object.freeze({
248	        status: "created" as const,
249	        userId: input.userId,
250	        auditToken: input.auditToken,
251	        channelBindingId: emailChannel.rows[0]!.channel_binding_id
252	      });
253	    });
254	  }
255	
256	  async findAuditIdentityByBlindIndex(emailBlindIndex: Buffer): Promise<{
257	    readonly auditToken: string;
258	    readonly addressKey: string;
259	  } | null> {
260	    const result = await this.pool.query<{ audit_token: string; address_key: string }>(`
261	      SELECT audit_token,encode(email_blind_index,'hex') AS address_key
262	      FROM identity."user" WHERE email_blind_index=$1
263	    `, [emailBlindIndex]);
264	    const row = result.rows[0];
265	    return row === undefined ? null : Object.freeze({
266	      auditToken: row.audit_token,
267	      addressKey: row.address_key
268	    });
269	  }
270	
271	  async findAuditIdentityByVerificationHash(tokenHash: string): Promise<{
272	    readonly auditToken: string;
273	    readonly addressKey: string;
274	  } | null> {
275	    const result = await this.pool.query<{ audit_token: string; address_key: string }>(`
276	      SELECT u.audit_token,encode(u.email_blind_index,'hex') AS address_key
277	      FROM identity.verification_token_credential token
278	      JOIN identity.channel_binding c ON c.channel_binding_id=token.channel_binding_id
279	      JOIN identity."user" u ON u.user_id=c.user_id
280	      WHERE token.token_hash=$1 AND c.channel_type='email'
281	    `, [tokenHash]);
282	    const row = result.rows[0];
283	    return row === undefined ? null : Object.freeze({
284	      auditToken: row.audit_token,
285	      addressKey: row.address_key
286	    });
287	  }
288	
289	  async recordVerificationDelivery(input: {
290	    readonly userId: string;
291	    readonly occurredAt: Date;
292	    readonly source: AuthSourceContext;
293	    readonly success: boolean;
294	    readonly errorCode: string | null;
295	  }): Promise<void> {
296	    await this.transaction(async (client) => {
297	      const user = await client.query<{ audit_token: string }>(`
298	        SELECT audit_token FROM identity."user" WHERE user_id=$1 FOR UPDATE
299	      `, [input.userId]);
300	      if (user.rows[0] === undefined) throw new Error("IDENTITY_USER_NOT_FOUND");
301	      await client.query(`
302	        UPDATE identity.channel_binding
303	        SET verification_last_sent_at=$2,delivery_status=$3,delivery_error=$4
304	        WHERE user_id=$1 AND channel_type='email'
305	      `, [input.userId, input.occurredAt, input.success ? "sent" : "failed", input.errorCode]);
306	      await this.appendAudit(client, {
307	        actorToken: user.rows[0].audit_token,
308	        eventType: "identity.verification.sent",
309	        targetType: "identity.channel_binding",
310	        occurredAt: input.occurredAt,
311	        source: input.source,
312	        decision: "ALLOW",
313	        success: input.success,
314	        justification: input.errorCode
315	      });
316	    });
317	  }
318	
319	  async recordVerificationDeliveryRecordFailure(input: {
320	    readonly userId: string;
321	    readonly correlationId: string;
322	    readonly occurredAt: Date;
323	    readonly source: AuthSourceContext;
324	    readonly errorCode: "MAIL_RECORD_FAILED";
325	  }): Promise<void> {
326	    await this.transaction(async (client) => {
327	      const user = await client.query<{ audit_token: string }>(`
328	        SELECT audit_token FROM identity."user" WHERE user_id=$1 FOR UPDATE
329	      `, [input.userId]);
330	      if (user.rows[0] === undefined) throw new Error("IDENTITY_USER_NOT_FOUND");
331	      await this.appendAudit(client, {
332	        actorToken: user.rows[0].audit_token,
333	        eventType: "identity.verification.delivery_record_failed",
334	        targetType: "identity.channel_binding",
335	        occurredAt: input.occurredAt,
336	        source: input.source,
337	        decision: "DENY",
338	        success: false,
339	        justification: `correlation:${input.correlationId};code:${input.errorCode}`
340	      });
341	    });
342	  }
343	
344	  async recordDuplicateRegistrationPostwork(input: {
345	    readonly userId: string;
346	    readonly occurredAt: Date;
347	    readonly source: AuthSourceContext;
348	  }): Promise<void> {
349	    await this.transaction(async (client) => {
350	      const user = await client.query<{ audit_token: string }>(`
351	        SELECT audit_token FROM identity."user" WHERE user_id=$1 FOR UPDATE
352	      `, [input.userId]);
353	      if (user.rows[0] === undefined) throw new Error("IDENTITY_USER_NOT_FOUND");
354	      await client.query(`
355	        UPDATE identity.channel_binding SET state=state
356	        WHERE user_id=$1 AND channel_type='email'
357	      `, [input.userId]);
358	      await this.appendAudit(client, {
359	        actorToken: user.rows[0].audit_token,
360	        eventType: "identity.registration.duplicate_postwork",
361	        targetType: "identity.channel_binding",
362	        occurredAt: input.occurredAt,
363	        source: input.source,
364	        decision: "DENY",
365	        success: false,
366	        justification: "REGISTRATION_ADDRESS_UNAVAILABLE"
367	      });
368	    });
369	  }
370	
371	  async consumeVerification(input: {
372	    readonly tokenHash: string;
373	    readonly occurredAt: Date;
374	    readonly source: AuthSourceContext;
375	  }): Promise<boolean> {
376	    return this.transaction(async (client) => {
377	      const found = await client.query<{
378	        token_hash: string;
379	        channel_binding_id: string;
380	        user_id: string;
381	        audit_token: string;
382	        expires_at: Date;
383	        consumed_at: Date | null;
384	        user_state: string;
385	      }>(`
386	        SELECT token.token_hash,c.channel_binding_id,c.user_id,u.audit_token,
387	          token.expires_at,token.consumed_at,u.state AS user_state
388	        FROM identity.verification_token_credential token
389	        JOIN identity.channel_binding c ON c.channel_binding_id=token.channel_binding_id
390	        JOIN identity."user" u ON u.user_id=c.user_id
391	        WHERE token.token_hash=$1 AND c.channel_type='email'
392	        FOR UPDATE OF token,c,u
393	      `, [input.tokenHash]);
394	      const row = found.rows[0];
395	      const valid = row !== undefined
396	        && row.consumed_at === null
397	        && row.expires_at.getTime() >= input.occurredAt.getTime()
398	        && row.user_state === "pending_verification";
399	      const actorToken = row?.audit_token ?? randomUUID();
400	      if (valid) {
401	        await client.query(`
402	          UPDATE identity.verification_token_credential SET consumed_at=$2
403	          WHERE channel_binding_id=$1 AND consumed_at IS NULL
404	        `, [row.channel_binding_id, input.occurredAt]);
405	        await client.query(`
406	          UPDATE identity.channel_binding
407	          SET state='verified',verified_at=$2,verification_consumed_at=$2,
408	            delivery_error=NULL
409	          WHERE channel_binding_id=$1
410	        `, [row.channel_binding_id, input.occurredAt]);
411	        await client.query(`UPDATE identity."user" SET state='active' WHERE user_id=$1`, [row.user_id]);
412	      }
413	      await this.appendAudit(client, {
414	        actorToken,
415	        eventType: "identity.verification.consumed",
416	        targetType: "identity.channel_binding",
417	        occurredAt: input.occurredAt,
418	        source: input.source,
419	        decision: valid ? "ALLOW" : "DENY",
420	        success: valid,
421	        justification: valid ? null : "VERIFICATION_TOKEN_INVALID"
422	      });
423	      return valid;
424	    });
425	  }
426	
427	  async prepareVerificationResend(input: {
428	    readonly emailBlindIndex: Buffer;
429	    readonly tokenHash: string;
430	    readonly expiresAt: Date;
431	    readonly occurredAt: Date;
432	    readonly cooldownMs: number;
433	    readonly source: AuthSourceContext;
434	  }): Promise<ResendPreparation> {
435	    return this.transaction(async (client) => {
436	      const found = await client.query<{
437	        channel_binding_id: string;
438	        user_id: string;
439	        audit_token: string;
440	        state: string;
441	        verification_last_sent_at: Date | null;
442	      }>(`
443	        SELECT c.channel_binding_id,c.user_id,u.audit_token,u.state,c.verification_last_sent_at
444	        FROM identity."user" u
445	        JOIN identity.channel_binding c ON c.user_id=u.user_id AND c.channel_type='email'
446	        WHERE u.email_blind_index=$1
447	        FOR UPDATE OF c,u
448	      `, [input.emailBlindIndex]);
449	      const row = found.rows[0];
450	      const cooling = row?.verification_last_sent_at !== null && row?.verification_last_sent_at !== undefined
451	        && input.occurredAt.getTime() - row.verification_last_sent_at.getTime() < input.cooldownMs;
452	      const send = row !== undefined && row.state === "pending_verification" && !cooling;
453	      const actorToken = row?.audit_token ?? randomUUID();
454	      if (send) {
455	        await client.query(`
456	          DELETE FROM identity.verification_token_credential
457	          WHERE channel_binding_id=$1 AND expires_at < $2
458	        `, [row.channel_binding_id, input.occurredAt]);
459	        await client.query(`
460	          INSERT INTO identity.verification_token_credential (
461	            token_hash,channel_binding_id,issued_at,expires_at
462	          ) VALUES ($1,$2,$3,$4)
463	        `, [input.tokenHash, row.channel_binding_id, input.occurredAt, input.expiresAt]);
464	        await client.query(`
465	          UPDATE identity.channel_binding
466	          SET verification_token_hash=$2,verification_expires_at=$3,
467	            verification_consumed_at=NULL,verification_last_sent_at=$4,
468	            delivery_status='pending',delivery_error=NULL
469	          WHERE channel_binding_id=$1
470	        `, [row.channel_binding_id, input.tokenHash, input.expiresAt, input.occurredAt]);
471	      }
472	      await this.appendAudit(client, {
473	        actorToken,
474	        eventType: "identity.verification.resend_requested",
475	        targetType: "identity.channel_binding",
476	        occurredAt: input.occurredAt,
477	        source: input.source,
478	        decision: send ? "ALLOW" : "DENY",
479	        success: send,
480	        justification: send ? null : cooling ? "RESEND_COOLDOWN" : "RESEND_NOT_APPLICABLE"
481	      });
482	      return send ? Object.freeze({
483	        status: "send" as const,
484	        userId: row.user_id,
485	        auditToken: row.audit_token,
486	        channelBindingId: row.channel_binding_id
487	      }) : Object.freeze({ status: "ignored" as const });
488	    });
489	  }
490	
491	  async recordRateLimitRefusal(input: {
492	    readonly actorToken: string;
493	    readonly route: "register" | "verify" | "resend";
494	    readonly scope: "ip" | "address";
495	    readonly count: number;
496	    readonly ipCount: number;
497	    readonly addressCount: number;
498	    readonly occurredAt: Date;
499	    readonly aggregateWindowStartedAt: Date;
500	    readonly source: AuthSourceContext;
501	  }): Promise<void> {
502	    if (!Number.isSafeInteger(input.count) || input.count < 1
503	      || !Number.isSafeInteger(input.ipCount) || input.ipCount < 0
504	      || !Number.isSafeInteger(input.addressCount) || input.addressCount < 0
505	      || input.ipCount + input.addressCount !== input.count) {
506	      throw new TypeError("RATE_LIMIT_REFUSAL_AGGREGATE_INVALID");
507	    }
508	    await this.transaction((client) => this.appendAudit(client, {
509	      actorToken: input.actorToken,
510	      eventType: "identity.auth.rate_limit_refused",
511	      targetType: `auth.${input.route}`,
512	      occurredAt: input.occurredAt,
513	      source: input.source,
514	      decision: "DENY",
515	      success: false,
516	      justification: `aggregate:route-window;route:${input.route};window:${input.aggregateWindowStartedAt.toISOString()}`
517	        + `;count:${input.count};ip_count:${input.ipCount};address_count:${input.addressCount}`
518	    }));
519	  }
520	
521	  async recordRegistrationFailure(input: {
522	    readonly correlationId: string;
523	    readonly occurredAt: Date;
524	    readonly source: AuthSourceContext;
525	  }): Promise<void> {
526	    await this.transaction((client) => this.appendAudit(client, {
527	      actorToken: input.correlationId,
528	      eventType: "identity.registration.failed",
529	      targetType: "identity.registration_attempt",
530	      occurredAt: input.occurredAt,
531	      source: input.source,
532	      decision: "DENY",
533	      success: false,
534	      justification: "PROVISION_FAILED"
535	    }));
536	  }
537	}
