  const directory = await mkdtemp(join(tmpdir(), "debateai-s00-postgres-"));
  const port = await reservePort();
  const embedded = new EmbeddedPostgres({
    databaseDir: join(directory, "data"),
    user: "debateai",
    password: "debateai-test-only",
    port,
    persistent: false,

