// Determines the real row-lock acquisition order of `FOR UPDATE OF c,u`
// against a real PostgreSQL of the same major version the suite uses.
import { startTestDatabase } from "/Users/vladmihaimiron/Documents/DebateAIRO/dialectical-engine/tests/support/testDatabase.js";

const database = await startTestDatabase();

async function probe(label: string, sql: string): Promise<void> {
  await database.pool.query(`DROP TABLE IF EXISTS c; DROP TABLE IF EXISTS u;`);
  await database.pool.query(`CREATE TABLE u (user_id int primary key)`);
  await database.pool.query(`CREATE TABLE c (channel_id int primary key, user_id int not null)`);
  await database.pool.query(`INSERT INTO u VALUES (1)`);
  await database.pool.query(`INSERT INTO c VALUES (10,1)`);

  const holder = await database.pool.connect();
  const runner = await database.pool.connect();
  const prober = await database.pool.connect();
  try {
    // Holder takes ONLY the u row.
    await holder.query("BEGIN");
    await holder.query("SELECT user_id FROM u WHERE user_id=1 FOR UPDATE");

    // Runner runs the join lock; it must block on u.
    await runner.query("BEGIN");
    const blocked = runner.query(sql);
    let settled = false;
    blocked.then(() => { settled = true; }, () => { settled = true; });
    await new Promise((resolve) => setTimeout(resolve, 1200));
    console.info(`[${label}] runner_settled_while_u_held=${settled}`);

    // Did the runner already take c before blocking on u?
    await prober.query("BEGIN");
    let cAlreadyLocked: boolean;
    try {
      await prober.query("SELECT channel_id FROM c WHERE channel_id=10 FOR UPDATE NOWAIT");
      cAlreadyLocked = false;
    } catch (error) {
      cAlreadyLocked = (error as { code?: string }).code === "55P03";
      if (!cAlreadyLocked) throw error;
    }
    await prober.query("ROLLBACK");

    console.info(
      `[${label}] c_locked_before_blocking_on_u=${cAlreadyLocked} => order=${cAlreadyLocked ? "c THEN u" : "u THEN c"}`
    );

    await holder.query("ROLLBACK");
    await blocked;
    await runner.query("ROLLBACK");
  } finally {
    holder.release();
    runner.release();
    prober.release();
  }
}

