    const invokeRealRoute = async (
      flow: ReturnType<typeof buildService>,
      route: typeof routes[number],
      label: string
    ): Promise<string> => {
      const realSource = {
        ip: `s3c-b2-real-innocent:${label}`,
        userAgent: "vitest-s3c-b2-real-route",
        requestId: `request:s3c:b2:${label}`
      };
