            ip: `2001:db8:3d:456::${((offset + index) % 512) + 1}`,
            userAgent: "vitest-s3d-rss-refusal",
            requestId: `request:s3d:rss:refusal:${offset + index}`
          });
        } catch (error) {
          if ((error as { code?: string }).code === "AUTH_MAIL_BUSY") busy += 1;
        }
      }
