      waveHeapUsedMib.push(memory.heapUsed / 1024 / 1024);
      waveHeapTotalMib.push(memory.heapTotal / 1024 / 1024);
      waveExternalMib.push(memory.external / 1024 / 1024);
    }
    const plateauSamples = waveRssMib.slice(12);
