        this.active += 1;
        if (!this.passThrough) {
          await new Promise<void>((resolve) => this.releases.push(resolve));
        }
        this.active -= 1;
      }

      releaseAll(): void {
        this.passThrough = true;
        for (const release of this.releases.splice(0)) release();
      }

      startHanging(): void {
