      await stat(loadPath);
      writes += 1;
    }
  })();
  return Object.freeze({
    filesystemWrites: () => writes,
    async stop() {
      running = false;
      await Promise.all(cpuWorkers.map((worker) => worker.terminate()));
      await filesystemWork;
      await rm(loadPath, { force: true });
    }
  });
}

