input.old_string:
/**
 * Waits on a client reserved before the burst so the probe itself never
 * competes for the connection pool it is observing.
 */
async function waitForRowLockWaiters(
  monitor: PoolClient,
  minimumWaiters: number,
  timeoutMs: number
): Promise<number> {
  const deadline = performance.now() + timeoutMs;
  let observed = 0;
  while (performance.now() < deadline) {
    const waiting = await monitor.query<{ waiters: string }>(`
      SELECT count(*)::text AS waiters FROM pg_stat_activity
      WHERE datname=current_database() AND wait_event_type='Lock'
    `);
    observed = Math.max(observed, Number(waiting.rows[0]!.waiters));
    if (observed >= minimumWaiters) return observed;
    await new Promise<void>((resolve) => setTimeout(resolve, 20));
  }
  return observed;
}

