    const durableStore = new FileUserDekStore(secretRoot, loadKek(Buffer.alloc(32, 0x7d)));
    const flow = buildService({
      clock: () => draining
        ? new Date(drainTime)
        : new Date(requestedBase.getTime() + intakeClockCalls++),
