      expect(row.verification_expires_at).toEqual(
        new Date(expectedRequestedAt.getTime() + basePolicy.verification.tokenTtlMs)
      );
      drifts.push(Math.abs(row.adult_affirmed_at.getTime() - expectedRequestedAt.getTime()));
    }
