      requestId: "request:s3b:commit-gate"
    }).then((response) => {
      settledBeforeRelease += 1;
      return response;
    });

    await storeEntered;
    await new Promise<void>((resolve) => setTimeout(
      resolve,
      basePolicy.verification.enumerationResponseFloorMs
        + basePolicy.verification.enumerationToleranceMs
