      expect(generatedTokenStringsInSnapshot).toHaveLength(ruledMaximum);
      expect(rawTokensOutsideActiveSend).toBe(0);
      expect(mail.peak).toBeLessThanOrEqual(ruledMaximum);
      expect(acceptedAtSaturation).toBe(ruledMaximum);
