    expect(outcomes[0]).toEqual(expect.objectContaining({
      code: "AUTH_MAIL_BUSY",
      statusCode: 503
    }));
    flow.service.drainMailCapacitySignals();
  }, 60_000);

  it("S3d rework3 fold-in plateaus RSS under a fixed ceiling and preserves the total aggregate count", async () => {
