    };
    const duplicateAtCapacity = await saturationProbe("s3d-hang-0@example.test", "duplicate");
    const newAtCapacity = await saturationProbe("s3d-hang-new-at-capacity@example.test", "new");
    const overflow = async (index: number) => {
