    const error = vi.spyOn(console, "error").mockImplementation(() => undefined);
    flow.advance(60_000);
    try {
      await expect(flow.service.verifyEmail({ token }, source))
        .rejects.toMatchObject({ code: "AUTH_RATE_LIMITED", statusCode: 429 });
