        expect(observation.rejection).toBeNull();
      }
      expect(observations.filter((observation) => observation.body !== RESEND_BODY)).toEqual([]);
      expect(observedDeliveryErrors).toEqual([]);
      expect(deadlocksAfter - deadlocksBefore).toBe(0);

